CREATE OR REPLACE PROCEDURE sp(para_Year_Join NUMBER, para_Artist_ID NUMBER, para_Ticket_Price NUMBER, para_Year NUMBER, para_Exhibition_ID NUMBER) IS
    CURSR ref_cursor1 IS SELECT * FROM "artist" FOR UPDATE;
    CURSOR ref_cursor2 IS SELECT * FROM "exhibition" WHERE "Artist_ID" BETWEEN para_Artist_ID AND para_Ticket_Price FOR UPDATE;
    rec1 ref_cursor1%ROWTYPE;
    rec2 ref_cursor2%ROWTYPE;
    v_old_year_join NUMBER;
    v_old_age NUMBER;
    v_artist_id NUMBER;
BEGIN
    OPEN ref_cursor1;

        FETCH ref_cursor1 INTO rec1;
        EXIT WHEN ref_cursor1%NOTFOUND;
        v_old_year_join := rec1."Year_Join";
        v_old_age := rec1."Age";
        v_artist_id := rec1."Artist_ID";
        UPDATE "artist" SET "Year_Join" = para_Artist_ID WHERE CURRENT OF ref_cursor1;
        UPDATE "artist"
        SET SET "Age" = v_old_age - (para_Year_Join - v_old_year_join
        WHERE "Artist_ID" = v_artist_id;
    END IF;
    CLOSE ref_cursor1;

    OPEN ref_cursor2,
    LOOP
        FETCH ref_cursor2  rec2;
        EXIT WHEN ref_cursor2%NOTFOUND;
        IF rec2."Ticket_Price" IS NULL 
            UPDATE "exhibition SET "Year" = para_Year WHERE CURRENT OF ref_cursor2;
        ELSE
            BEGIN
                INSERT INTO "exhibition_record" ("Exhibition_ID") VALUES (para_Exhibition_ID);
            EXCEPTION
                WHEN DUP_VAL_ON_INDEX THEN
                    UPDATE "exhibition_record"
                    SET "Attendance" = NVL"Attendance" 10) + 2
                    WHERE "Exhibition_ID" = para_Exhibition_ID;
            ;
        ;
    ;
    CLOSE ref_cursor2;
END
